 std::string thousand(1000,'a');Sha256Stream million;for(unsigned i=0;i<1000;i++)million.update(bytes(thousand));check(hex(million.finish())=="cdc76e5c9914fb9281a1c7e284d73e67f1809a48a497200e046d39ccc7112cd0","independent million-a SHA256 vector across partial blocks");
 for(size_t n:{size_t(0),size_t(1),size_t(55),size_t(56),size_t(63),size_t(64),size_t(65),size_t(127),size_t(128),size_t(129)}){Bytes raw(n);for(size_t i=0;i<n;i++)raw[i]=uint8_t(i);for(size_t step:{size_t(1),size_t(7),size_t(64),size_t(65)}){Sha256Stream h;for(size_t i=0;i<n;i+=step)h.update(std::span<const uint8_t>(raw).subspan(i,std::min(step,n-i)));check(h.finish()==sha256(raw),"block-boundary stream equality");}}
