World legacy_world(World w,int32_t scale){std::vector<Cell> dense;dense.reserve(size_t(w.terrain.width)*w.terrain.height);for(int32_t z=0;z<w.terrain.height;z++)for(int32_t x=0;x<w.terrain.width;x++)dense.push_back(w.terrain.at(x,z));w.terrain.profile=1;w.terrain.cell_mm=scale;w.terrain.cells=std::move(dense);w.terrain.rows.clear();w.terrain.fine_patches.clear();auto&p=std::get<Json::Object>(w.provenance.value);for(auto key:{"terrain_profile","surface_micro_um","micro_divisions"})p.erase(key);if(scale==2000){for(auto key:{"terrain_cell_mm","core_physical_width_mm","core_physical_height_mm","domain_physical_width_mm","domain_physical_height_mm"})p.erase(key);}else{p["terrain_cell_mm"]=scale;p["core_physical_width_mm"]=int64_t(w.terrain.width-16)*scale;p["core_physical_height_mm"]=int64_t(w.terrain.height-16)*scale;p["domain_physical_width_mm"]=int64_t(w.terrain.width)*scale;p["domain_physical_height_mm"]=int64_t(w.terrain.height)*scale;}p["surface_sha256"]=hex(w.terrain.surface_hash());w.validate(w.definition_hash);return w;}
uint64_t save_integer(std::span<const uint8_t>b,size_t pos,unsigned n){uint64_t v=0;for(unsigned i=0;i<n;i++)v|=uint64_t(b[pos+i])<<(8*i);return v;}
Json saved_terrain(const Bytes&b){size_t entry=184;auto off=save_integer(b,entry+8,8),length=save_integer(b,entry+16,8);return parse_json(std::string_view(reinterpret_cast<const char*>(b.data()+off),size_t(length)));}
Bytes change_saved_terrain(const Bytes&original,const std::function<void(Json&)>&change){
 // A malformed logical payload with genuinely rebuilt integrity hashes must
 // still be rejected by typed terrain admission, rather than only by SHA256.
 Bytes header(original.begin(),original.begin()+120),table(original.begin()+120,original.begin()+632);std::vector<Bytes>payloads;uint64_t offset=632;
 auto set=[&](size_t pos,uint64_t value,unsigned n){for(unsigned i=0;i<n;i++)table[pos+i]=uint8_t(value>>(8*i));};
 for(size_t i=0;i<8;i++){size_t entry=i*64;auto off=save_integer(table,entry+8,8),length=save_integer(table,entry+16,8);Bytes payload(original.begin()+ptrdiff_t(off),original.begin()+ptrdiff_t(off+length));if(i==1){auto j=parse_json(std::string_view(reinterpret_cast<const char*>(payload.data()),payload.size()));change(j);auto s=canonical_json(j);payload.assign(s.begin(),s.end());}set(entry+8,offset,8);set(entry+16,payload.size(),8);auto hash=sha256(payload);std::copy(hash.begin(),hash.end(),table.begin()+ptrdiff_t(entry+32));offset+=payload.size();payloads.push_back(std::move(payload));}
 auto hash=sha256(table);std::copy(hash.begin(),hash.end(),header.begin()+88);header.insert(header.end(),table.begin(),table.end());for(auto&p:payloads)header.insert(header.end(),p.begin(),p.end());return header;
}
