 d=draft();d.core_width=4096;d.core_height=2048;auto big=create_candidate(d,defs);check(big.terrain.width==4112&&big.terrain.height==2064&&big.terrain.cells.empty()&&big.terrain.fine_patches.empty()&&big.terrain.storage_bytes()<1048576,"8.192 by4.096km world real RLE storage below1MiB");check(big.terrain.dry_micro_count()==uint64_t(4096)*2048*4096&&big.provenance.at("core_physical_width_mm").integer()==8192000,"large real physical domain/area");auto big_save=encode_save(big);check(big_save.size()<1048576&&decode_save(big_save,defs).deterministic_hash()==big.deterministic_hash(),"large world actually saves and loads compactly");
