 d=draft();d.kind=CreationKind::Earth;d.selection={-180000000,180000000,-90000000,90000000};d.core_width=64;auto global=create_candidate(d,defs,&g);check(global.terrain.width==80&&global.terrain.height==48,"full360/180 source rectangle no60degree cap");int polls=0;reject([&]{create_candidate(d,defs,&g,[&]{return ++polls>10;});},"CREATION_CANCELED");d.budget_bytes=4096;reject([&]{create_candidate(d,defs,&g);},"CREATION_BUDGET");
