void antarctic_topology(const fs::path&root){
 Bytes b;
 ring(b,4,5,-1,{{180000000,-70000000},{90000000,-71000000},{0,-72000000},{-90000000,-71000000},{-180000000,-70000000}},true);
 ring(b,145,5,-1,{{80000000,-66000000},{82000000,-66000000},{82000000,-65000000},{80000000,-65000000},{80000000,-66000000}});
 ring(b,146,6,-1,{{100000000,-66000000},{102000000,-66000000},{102000000,-65000000},{100000000,-65000000},{100000000,-66000000}});
 write(root/"antarctic.b",b);Geography g(root/"antarctic.b",sha256(b));
 check(g.polygon_count()==2,"ice-front ordinary islands admitted, grounding-line excluded");
 check(g.land(81000000,-65500000),"ordinary closed L5 island keeps its real interior");
 check(!g.land(83000000,-65500000)&&!g.land(101000000,-65500000),"island not extended to pole; L6 not land");
 check(g.land(0,-75000000)&&g.land(179000000,-75000000)&&g.land(-179000000,-75000000),"pole-winding mainland fills south on both meridians");
 check(!g.land(0,-60000000),"polar closure does not fabricate northern land");
 auto values=g.sample({-5000000,5000000,-80000000,-73000000},10,7);
 check(std::all_of(values.begin(),values.end(),[](auto v){return v==1;}),"exact scanline samples the real polar interior");
 Bytes malformed;ring(malformed,4,5,-1,{{180000000,-70000000},{90000000,-71000000},{0,-72000000},{-90000000,-71000000},{-180000000,-70000000}});
 write(root/"bad-polar.b",malformed);reject([&]{Geography bad(root/"bad-polar.b",sha256(malformed));},"GEO_RING_INVALID");
}
void authority(const DefinitionPackage&defs){auto w=create_candidate(draft(),defs);Authority a(w,7);Envelope e{w.id,7,w.revision,1,"rename-first"};Command c{Command::Kind::RenameWorld,"Neue Ähren · 新世界"};auto before=a.world().deterministic_hash();auto p=a.prepare(e,c);check(a.world().deterministic_hash()==before,"prepare is read-only");auto receipt=a.commit(p);check(a.world().name==c.text&&a.world().tick==0&&a.world().boundary_ordinal==1,"paused commit has zero elapsed ticks");auto once=a.world().deterministic_hash();check(a.commit(p).committed_revision==receipt.committed_revision&&a.world().deterministic_hash()==once,"committed idempotency retry");c.text="Different";reject([&]{a.prepare(e,c);},"IDEMPOTENCY_CONFLICT");e.command_id="late";e.input_sequence=2;reject([&]{a.prepare(e,c);},"STALE_REVISION");e.expected_revision=a.world().revision;e.session_generation=6;reject([&]{a.prepare(e,c);},"STALE_GENERATION");e.session_generation=7;auto stale=a.prepare(e,c);a.advance_tick();reject([&]{a.commit(stale);},"STALE_REVISION");e.expected_revision=a.world().revision;e.command_id="auto-age";Command auto_age{Command::Kind::SetAgeAutomatic};auto_age.boolean=true;auto_age.light_duration_tick=2;auto_age.dark_duration_tick=3;a.commit(a.prepare(e,auto_age));auto trace=a.advance_tick();check(trace.phases.size()==11&&trace.phases[10]=="PUBLISH"&&a.world().age.remaining_tick==1,"11 barriers and age remainder");a.advance_tick();check(a.world().age.current==Age::Darkness&&a.world().age.remaining_tick==3,"automatic exact age expiry");e.expected_revision=a.world().revision;e.input_sequence=3;e.command_id="manual-age";Command manual{Command::Kind::SetAge};manual.age=Age::Light;a.commit(a.prepare(e,manual));check(!a.world().age.automatic&&a.world().age.remaining_tick==0,"manual atomically disables auto");e.expected_revision=a.world().revision;e.input_sequence=4;e.command_id="set-rule";Command rule{Command::Kind::SetRule,"hunger_consequences",false};a.commit(a.prepare(e,rule));check(!a.world().rules.at("hunger_consequences")&&a.world().population==0,"rule persist no free life");auto sd=draft();sd.kind=CreationKind::BlankSea;Authority fill(create_candidate(sd,defs),9);Command fc{Command::Kind::FillWaterOnly};fc.cell_x=9;fc.cell_z=9;fc.land_kind=TerrainKind::Soil;fc.soil_theme=5;Envelope fe{fill.world().id,9,1,1,"reclaim"};auto fp=fill.prepare(fe,fc);check(fill.world().terrain.sample_cell(9,9,0,0).kind==TerrainKind::CloseOcean,"fill prepare has no half write");auto fr=fill.commit(fp);check(fill.world().terrain.sample_cell(9,9,0,0)==Cell{TerrainKind::Soil,5,2}&&fill.world().terrain.dry_micro_count()==4096,"actual authority fill commits only wet microcolumns");auto filled=fill.world().deterministic_hash();check(fill.commit(fp).committed_revision==fr.committed_revision&&fill.world().deterministic_hash()==filled,"fill receipt retry does not repeat revision");check(decode_save(encode_save(fill.world()),defs).deterministic_hash()==filled,"modified terrain original-source proof and current surface save separately");std::atomic_bool rejected=false;std::thread other([&]{try{a.advance_tick();}catch(const Error&err){rejected=err.code=="NOT_SINGLE_WRITER";}});other.join();check(rejected,"single-writer thread");}
void save_and_session(const fs::path&root,const DefinitionPackage&defs){auto w=create_candidate(draft(),defs);auto bytes=encode_save(w);check(bytes.size()>632&&std::string(bytes.begin(),bytes.begin()+8)=="SONNSAV1"&&bytes[8]==1&&bytes[16]==8,"actual 120B header eight64B entries");check(bytes[120]==1&&bytes[184]==2&&bytes[248]==3,"entry width64");auto fine_readback=decode_save(bytes,defs);auto fine_support=fine_readback.terrain.support(17000,17000);check(fine_readback.terrain.profile==2&&fine_support&&fine_support->height_mm==0&&fine_readback.deterministic_hash()==w.deterministic_hash(),"complete sparse geometry save readback");
 auto legacy=legacy_world(w,2000);auto legacy_bytes=encode_save(legacy);auto legacy_readback=decode_save(legacy_bytes,defs);check(legacy_readback.terrain.profile==1&&legacy_readback.terrain.cell_mm==2000&&legacy_readback.terrain.support(17000,17000)->height_mm==2000&&encode_save(legacy_readback)==legacy_bytes,"legacy schema1 metric and bytes preserved");
 auto corrupt=bytes;corrupt.back()^=1;reject([&]{decode_save(corrupt,defs);},"SAVE_HASH");corrupt=bytes;corrupt[8]=2;reject([&]{decode_save(corrupt,defs);},"SAVE_VERSION");auto wrong=defs;wrong.hash[0]^=1;reject([&]{decode_save(bytes,wrong);},"DEFINITION_MISSING");wrong=defs;wrong.asset_hash[0]^=1;reject([&]{decode_save(bytes,wrong);},"ASSET_MISSING");
 SaveStore store(root/"save");auto first=store.save(w,defs);check(first.status==SaveStatus::Committed&&store.continue_world(defs)->deterministic_hash()==w.deterministic_hash(),"durable checkpoint before Continue");auto changed=w;changed.name="Changed";changed.revision=2;
 for(auto fault:{SaveFault::BeforeWrite,SaveFault::ShortWrite,SaveFault::FileFlush,SaveFault::Readback,SaveFault::RenameCheckpoint,SaveFault::CheckpointDirectoryFlush,SaveFault::PointerWrite,SaveFault::PointerRename}){auto result=store.save(changed,defs,fault);check(result.status==SaveStatus::Failed,"precommit failure");check(store.continue_world(defs)->id==w.id&&store.continue_world(defs)->name==w.name,"old Continue preserved");}
 auto unknown=store.save(changed,defs,SaveFault::PointerDirectoryFlush);check(unknown.status==SaveStatus::DurabilityUnknown&&unknown.code=="DURABILITY_UNKNOWN","postrename unknown durability");SaveStore restart(root/"save");check(restart.continue_world(defs)->name==w.name,"restart does not trust pending success bit");check(restart.recover(unknown.filename,defs).name==changed.name,"explicit orphan recovery");reject([&]{restart.recover("../steal.sonnsave",defs);},"UNSAFE_PATH");WorldSession session;session.load_continue(store,defs);auto original=session.active()->world().deterministic_hash();auto d=draft();d.world_id=uuid_from_hex("22222222222222222222222222222222");d=session.begin(d);auto candidate=create_candidate(d,defs);session.cancel();Checkpoint result;check(!session.publish(d,candidate,store,defs,result)&&result.code=="STALE_GENERATION"&&session.active()->world().deterministic_hash()==original,"canceled late candidate cannot replace World");d=session.begin(d);candidate=create_candidate(d,defs);auto before_generation=session.generation();check(!session.publish(d,candidate,store,defs,result,SaveFault::PointerDirectoryFlush)&&session.active()->world().deterministic_hash()==original&&session.generation()==before_generation,"uncertain firstsave never publishes new World");check(session.publish(d,candidate,store,defs,result)&&session.active()->world().id==d.world_id&&session.generation()>before_generation&&!session.accepts(d),"same current candidate can safely retry");session.load_checkpoint(first.filename,store,defs);check(session.active()->world().id==w.id&&store.continue_world(defs)->id==w.id,"explicit selected load durably republishes Continue");auto generation=session.generation();session.return_to_menu();check(!session.active()&&session.generation()>generation&&!session.accepts(d),"menu isolates generation");}
void save_replacement_recovery(const fs::path&root,const DefinitionPackage&defs){
 auto old=create_candidate(draft(),defs);SaveStore store(root/"replacement");auto first=store.save(old,defs);check(first.status==SaveStatus::Committed,"old pack checkpoint");
 auto old_pointer=read_file(root/"replacement/continue.json");auto old_checkpoint=read_file(root/"replacement"/first.filename);
 auto next_defs=defs;next_defs.asset_hash[0]^=1;auto d=draft();d.world_id[0]^=1;auto next=create_candidate(d,next_defs);
 reject([&]{store.continue_world(next_defs);},"ASSET_MISSING");auto failed=store.save(next,next_defs,SaveFault::PointerRename);
 check(failed.status==SaveStatus::Failed&&read_file(root/"replacement/continue.json")==old_pointer,"incompatible old Continue preserved on failed replacement");
 check(store.continue_world(defs)->id==old.id,"old package can still decode retained pointer");
 auto published=store.save(next,next_defs);check(published.status==SaveStatus::Committed&&store.continue_world(next_defs)->id==next.id,"new package creates world without loading incompatible Continue");
 check(read_file(root/"replacement/continue_previous.json")==old_pointer&&read_file(root/"replacement"/first.filename)==old_checkpoint,"prior pointer and checkpoint bytes remain unchanged");
 write(root/"replacement/continue.json","{broken pointer");auto broken_pointer=read_file(root/"replacement/continue.json");
 reject([&]{store.continue_world(next_defs);},"INVALID_JSON");auto uncertain=store.save(next,next_defs,SaveFault::PointerDirectoryFlush);
 check(uncertain.status==SaveStatus::DurabilityUnknown,"bad pointer replacement still honours durability uncertainty");
 check(read_file(root/"replacement/continue_previous.json")==broken_pointer,"malformed prior pointer retained verbatim for recovery");
 reject([&]{store.continue_world(next_defs);},"INVALID_JSON");WorldSession recovered;recovered.load_checkpoint(published.filename,store,next_defs);
 check(recovered.active()->world().id==next.id&&store.continue_world(next_defs)->id==next.id,"explicit valid checkpoint recovery bypasses damaged old pointer");
 check(read_file(root/"replacement/continue_previous.json")==broken_pointer,"explicit recovery preserves damaged evidence instead of deleting it");
 for(auto fault:{SaveFault::PendingRemove,SaveFault::PendingDirectoryFlush}){
  SaveStore gated(root/(fault==SaveFault::PendingRemove?"pending-remove":"pending-flush"));auto baseline=gated.save(old,defs);check(baseline.status==SaveStatus::Committed,"reader gate fixture committed");
  WorldSession live;live.load_continue(gated,defs);auto before=live.active()->world().deterministic_hash();auto generation=live.generation();auto fresh=draft();fresh.world_id[0]^=2;fresh=live.begin(fresh);auto candidate=create_candidate(fresh,defs);Checkpoint outcome;
  check(!live.publish(fresh,candidate,gated,defs,outcome,fault)&&outcome.status==SaveStatus::DurabilityUnknown,"reader gate failure cannot claim committed publication");
  check(live.generation()==generation&&live.active()->world().deterministic_hash()==before,"uncertain gate preserves in-memory world and session");
  check(gated.recover(outcome.filename,defs).id==candidate.id,"uncertain candidate remains explicitly recoverable");
  check(outcome.reader_gate_restored&&outcome.reader_gate_error.empty(),"uncertain publication durably reinstalls reader gate");
  check(gated.continue_world(defs)->id==old.id,"both reader gate failure points retain old in-process Continue");
  SaveStore reopened(gated.root());check(reopened.continue_world(defs)->id==old.id,"new store reads old Continue after recovery gate flush");
  auto failed_retry=gated.save(candidate,defs,SaveFault::BeforeWrite);check(failed_retry.status==SaveStatus::Failed&&gated.continue_world(defs)->id==old.id,"failed retry does not clear conservative reader latch");
  check(live.publish(fresh,candidate,gated,defs,outcome)&&outcome.status==SaveStatus::Committed,"same candidate retry completes durable publication");
  check(live.generation()>generation&&gated.continue_world(defs)->id==candidate.id&&!fs::exists(gated.root()/"pending.json"),"successful retry clears latch and publishes candidate Continue");
  SaveStore after_retry(gated.root());check(after_retry.continue_world(defs)->id==candidate.id,"successful retry new Continue persists across store reconstruction");
 }
 SaveStore failed_gate(root/"pending-recovery-flush");auto baseline=failed_gate.save(old,defs);check(baseline.status==SaveStatus::Committed,"recovery flush fixture committed");auto prior=read_file(failed_gate.root()/"continue.json");
 auto fresh=draft();fresh.world_id[0]^=3;auto candidate=create_candidate(fresh,defs);auto unknown=failed_gate.save(candidate,defs,SaveFault::PendingDirectoryFlushAndRecoveryFlush);
 check(unknown.status==SaveStatus::DurabilityUnknown&&!unknown.reader_gate_restored&&unknown.reader_gate_error.find("SAVE_FLUSH")!=std::string::npos,"failed gate reinstallation is reported without claiming durable rollback");
 check(!fs::exists(failed_gate.root()/"pending.json")&&read_file(failed_gate.root()/"continue_previous.json")==prior,"failed gate flush preserves previous pointer bytes without falsely claiming installed gate");
 check(failed_gate.continue_world(defs)->id==old.id&&failed_gate.recover(unknown.filename,defs).id==candidate.id,"in-process latch rejects unconfirmed Continue while candidate remains recoverable");
 auto retry=failed_gate.save(candidate,defs);check(retry.status==SaveStatus::Committed&&failed_gate.continue_world(defs)->id==candidate.id,"successful retry clears latch after gate recovery itself failed");
 check(read_file(failed_gate.root()/"continue_previous.json")==prior,"retry preserves actual old pointer instead of promoting unconfirmed disk pointer to previous slot");
}
