int main(int argc,char**argv){fs::path root=fs::temp_directory_path()/("sonnheide-core-test-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));try{auto defs=definitions(root);json_and_hash();streaming_hash();rng();micro_codecs(defs);terrain(defs);geography(root,defs);antarctic_topology(root);authority(defs);save_and_session(root,defs);save_replacement_recovery(root,defs);write(root/"definition.json","bad");reject([&]{admit_definitions(root/"definitions.json",root);},"DEFINITION_HASH");
 if(argc==3){Geography actual(fs::path(argv[2])/"geo/gshhs_f.b",hash_from_hex("af9215d58ebc525b2d09654a89959829f09e6edc457f3666759cded37be4ecf6"));check(fs::exists(fs::path(argv[1])/"data/geo/gshhg_sources.lock.json"),"official source lock present");check(actual.polygon_count()==188268,"complete official source except 344 excluded grounding-line rings");check(actual.land(0,-80000000),"official pole-containing ice-front mainland");check(actual.land(-67658936,-66640321),"official ordinary closed L5 island boundary");check(actual.land(13405000,52520000),"Berlin official land");check(!actual.land(-30000000,30000000),"Atlantic official water");auto d=draft();d.kind=CreationKind::Earth;d.selection={-6000000,2000000,49000000,55000000};d.core_width=128;auto earth=create_candidate(d,defs,&actual);check(earth.terrain.width==144&&earth.terrain.height==112,"exact Earth aspect and guard");check(decode_save(encode_save(earth),defs).deterministic_hash()==earth.deterministic_hash(),"real-source Earth save readback");d.selection={18000000,20000000,58000000,60000000};d.core_width=4096;CreationMetrics metrics;auto generation_started=std::chrono::steady_clock::now();auto archipelago=create_candidate(d,defs,&actual,{},&metrics);auto generation_ms=std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now()-generation_started).count();check(archipelago.terrain.width==4112&&archipelago.terrain.height==4112&&!archipelago.terrain.fine_patches.empty()&&archipelago.terrain.storage_bytes()<d.budget_bytes,"real full-precision8.192km Stockholm archipelago within admitted budget");std::cout<<"Actual8.192km Earth: management="<<archipelago.terrain.width<<"x"<<archipelago.terrain.height<<" packed_patches="<<archipelago.terrain.fine_patches.size()<<" resident_geometry_bytes="<<archipelago.terrain.storage_bytes()<<" source_payload_bytes="<<metrics.source_storage_bytes<<" scratch_peak_payload_bytes="<<metrics.scratch_peak_bytes<<" edge_references="<<metrics.source_edge_references<<" intersections="<<metrics.intersection_work<<" generation_ms="<<generation_ms<<"\n";check(metrics.scratch_peak_bytes<=134217728&&metrics.geometry_bytes<=d.budget_bytes,"measured payload capacities bounded, not a fictitious RSS claim");auto archipelago_save=encode_save(archipelago);std::cout<<"Actual8.192km Earth save: file_bytes="<<archipelago_save.size()<<" terrain_segment_bytes="<<save_integer(archipelago_save,184+16,8)<<" compressed_patch_count="<<archipelago.terrain.fine_patches.size()<<" hash_stream_state_bytes="<<sizeof(Sha256Stream)<<"\n";check(decode_save(archipelago_save,defs).deterministic_hash()==archipelago.deterministic_hash(),"real complex8km coast actually saves and readbacks");}
 fs::remove_all(root);std::cout<<"Core S00/S01: "<<checks<<" invariant checks passed\n";return 0;
 }catch(const std::exception&e){std::cerr<<"Core check failed: "<<e.what()<<"\nfixtures: "<<root<<'\n';return 1;}}
